$writeCount = 0
foreach ($relPath in $files.Keys) {
    $fullPath = Join-Path $root $relPath
    $dir = Split-Path -Path $fullPath -Parent
    if (-not (Test-Path -LiteralPath $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }
    $bytes = [Convert]::FromBase64String($files[$relPath])
    [System.IO.File]::WriteAllBytes($fullPath, $bytes)
    Write-Host "  WROTE: $relPath" -ForegroundColor Green
    $writeCount++
}

Write-Host "`nDone. $writeCount file(s) written." -ForegroundColor Cyan
Write-Host "Run: pnpm dev --filter=web  and visit /instructor/dashboard to see the new sidebar." -ForegroundColor Cyan
Write-Host "Run git diff to review the changes before committing." -ForegroundColor Cyan